  ('os-none', 'OS-NONE', 'os-none', 'os', 'PC Builders Canada', 'No operating system', 'Ships without an OS installed. Choose this if you are supplying your own licence or installing Linux yourself.', 0, null, 999, 0, null, 'published', 'verified', 'new', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, '{"note":"The system is still tested before shipping, using our own bootable media."}'::jsonb),
  ('os-windows-11-home', 'OS-MS-W11HOME', 'os-windows-11-home', 'os', 'Microsoft', 'Windows 11 Home', 'Windows 11 Home licence, installed and updated before the system ships.', 15900, null, 999, 10, null, 'published', 'sample', 'new', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, '{"edition":"Home","delivery":"Pre-installed and activated","unverified":"Price is a placeholder. OEM licence cost depends on your Microsoft reseller account, not retail."}'::jsonb),
  ('os-windows-11-pro', 'OS-MS-W11PRO', 'os-windows-11-pro', 'os', 'Microsoft', 'Windows 11 Pro', 'Windows 11 Pro licence. Adds BitLocker, Remote Desktop host and domain join, the usual requirements for a work machine.', 23900, null, 999, 10, null, 'published', 'sample', 'new', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, '{"edition":"Pro","delivery":"Pre-installed and activated","unverified":"Price is a placeholder. OEM licence cost depends on your Microsoft reseller account, not retail."}'::jsonb),
  ('net-tplink-tl-sg108e', 'NET-TPL-SG108E', 'net-tplink-tl-sg108e', 'networking', 'TP-Link', 'TL-SG108E 8-Port Gigabit Easy Smart Switch', 'Eight gigabit ports with VLAN, QoS and IGMP snooping in a fanless metal case. The usual starting point when a flat home network needs segmenting without moving to a full managed stack.', 3999, null, 5, 3, null, 'published', 'verified', 'new', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, '{"ports":"8 x 1GbE RJ45","management":"Web-managed (Easy Smart)","vlan":"Port-based, tag-based and MTU VLAN","qos":"Yes, with IGMP snooping","jumbo_frame":"15K","cooling":"Fanless","mounting":"Desktop or wall","price_checked":"2026-09-27","sale_price_observed":"$34.99 on 2026-09-27","source":"Canada Computers"}'::jsonb),
  ('net-tplink-tl-sg108pe', 'NET-TPL-SG108PE', 'net-tplink-tl-sg108pe', 'networking', 'TP-Link', 'TL-SG108PE 8-Port Gigabit PoE+ Easy Smart Switch', 'The same eight gigabit ports as the SG108E, with four of them supplying PoE+ across a 64 W budget. Enough to run a pair of access points and a couple of cameras without separate power bricks.', 8999, null, 5, 3, null, 'published', 'verified', 'new', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, '{"ports":"8 x 1GbE RJ45","poe_ports":"4 x PoE+ (802.3af/at)","poe_budget_watts":64,"management":"Web-managed (Easy Smart)","vlan":"Port-based, tag-based and MTU VLAN","price_checked":"2026-09-27","source":"Canada Computers"}'::jsonb),
  ('net-ubiquiti-usw-flex-2-5g-5', 'NET-UBI-FLEX25G5', 'net-ubiquiti-usw-flex-2-5g-5', 'networking', 'Ubiquiti', 'UniFi USW-Flex-2.5G-5', 'Five 2.5GbE ports, managed through UniFi. The sensible upgrade once a NAS and a desktop both have 2.5G and a gigabit switch has become the bottleneck between them.', 7999, null, 5, 3, null, 'published', 'verified', 'new', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, '{"ports":"5 x 2.5GbE RJ45","switching":"Layer 2, IGMP snooping, port mirroring, spanning tree","management":"UniFi Network application","form_factor":"Desktop","price_checked":"2026-09-27","source":"Canada Computers","availability_note":"Was sold out online at the retailer on the check date; confirm supply before promising a ship date."}'::jsonb),
  ('net-ubiquiti-usw-flex-2-5g-8-poe', 'NET-UBI-FLEX25G8P', 'net-ubiquiti-usw-flex-2-5g-8-poe', 'networking', 'Ubiquiti', 'UniFi USW-Flex-2.5G-8-PoE', 'Eight-port PoE switch with a 10 GbE RJ45/SFP+ combination uplink, in a desktop shell meant for deployment outside a wiring closet. That uplink is the reason to pick it over a cheaper eight-port unit.', 28500, null, 5, 3, null, 'published', 'sample', 'new', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, '{"ports":"8 ports, all PoE+ capable","uplink":"1 x 10GbE RJ45 / SFP+ combination","management":"UniFi Network application","dimensions_mm":"99.6 x 163.7 x 31.7","price_checked":"2026-09-27","source":"Canada Computers","unverified":"Port speed and total PoE budget. The retailer listing described the access ports as 10/100/1000 while naming the model 2.5G, and gave no PoE wattage at all. Confirm both against Ubiquiti documentation before publishing this row.","availability_note":"Sold out online and in store at the retailer on the check date."}'::jsonb),
  ('nas-synology-ds224-plus', 'NAS-SYN-DS224P', 'nas-synology-ds224-plus', 'nas', 'Synology', 'DiskStation DS224+ (2-bay, diskless)', 'Two-bay DiskStation running DSM. Diskless, so pair it with a couple of NAS-rated drives in a mirror. The common first NAS for household backups, Time Machine targets and a media library.', 44999, null, 5, 3, null, 'published', 'sample', 'new', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, '{"bays":2,"drive_support":"SATA HDD or SSD, 3.5 inch or 2.5 inch","memory":"2 GB DDR4","network":"2 x 1GbE RJ45","usb":"2 x USB 3.2 Gen 1","power_draw_watts":15,"supplied":"Diskless - drives sold separately","price_checked":"2026-09-27","source":"Canada Computers","unverified":"Exact CPU model and maximum raw capacity. The retailer listing said only \"Intel Celeron 2 GHz\" and described the bays as SAS, which is wrong for this unit. Confirm against the Synology datasheet before publishing this row."}'::jsonb),
  ('nas-synology-ds423-plus', 'NAS-SYN-DS423P', 'nas-synology-ds423-plus', 'nas', 'Synology', 'DiskStation DS423+ (4-bay, diskless)', 'Four-bay DiskStation with two M.2 NVMe slots for read and write cache. Four bays is the point where you can run a single-drive-redundant array and still grow it, which two bays never really allows.', 74999, null, 5, 3, null, 'published', 'sample', 'new', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, '{"bays":4,"drive_support":"SATA HDD or SSD, 3.5 inch or 2.5 inch","cache_slots":"2 x M.2 2280 NVMe","memory":"2 GB DDR4","network":"2 x 1GbE RJ45","usb":"2 x USB 3.2 Gen 1","max_raw_capacity":"Up to 72 TB per the retailer listing","dimensions_mm":"166 x 199 x 223","supplied":"Diskless - drives sold separately","price_checked":"2026-09-27","source":"Canada Computers","unverified":"Exact CPU model, and the 72 TB maximum capacity figure. Both came from retailer copy rather than the Synology datasheet."}'::jsonb),
  ('hdd-wd-red-plus-8tb', 'HDD-WD-RED8TB', 'hdd-wd-red-plus-8tb', 'storage', 'Western Digital', 'WD Red Plus 8TB NAS HDD (WD80EFPX)', 'Eight terabytes of CMR NAS storage rated for 180 TB a year and continuous operation. CMR rather than SMR is the point: shingled drives behave badly during a RAID rebuild, which is exactly when you need them not to.', 50999, null, 5, 3, null, 'published', 'verified', 'new', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, 'sata', 8000, null, '{"rpm":5640,"cache_mb":256,"recording":"CMR","form_factor":"3.5 inch","workload_rating":"180 TB per year","warranty":"3-year limited","nas_rated":true,"price_checked":"2026-09-27","source":"Canada Computers"}'::jsonb),
  ('hdd-seagate-ironwolf-4tb', 'HDD-SEA-IW4TB', 'hdd-seagate-ironwolf-4tb', 'storage', 'Seagate', 'IronWolf 4TB NAS HDD (ST4000VN006)', 'Four terabytes rated for 24/7 NAS duty, with three years of Rescue data recovery included. A reasonable capacity per dollar for a first two-bay mirror.', 27999, null, 5, 3, null, 'published', 'verified', 'new', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, 'sata', 4000, null, '{"rpm":5400,"cache_mb":256,"form_factor":"3.5 inch","duty":"Rated for 24x7 operation","included":"3 years Rescue Data Recovery Services","warranty":"3-year limited","nas_rated":true,"price_checked":"2026-09-27","sale_price_observed":"$264.99 on 2026-09-27","source":"Canada Computers","availability_note":"Sold out online at the retailer on the check date; limited store stock."}'::jsonb),
  ('mini-rpi5-4gb', 'MINI-RPI5-4GB', 'mini-rpi5-4gb', 'mini-pc', 'Raspberry Pi', 'Raspberry Pi 5 / 4GB', 'The 4 GB Pi 5. Enough for Pi-hole, Home Assistant, a print server or a light Docker host. It needs a power supply, storage and cooling, none of which are in the box.', 15395, null, 5, 3, null, 'published', 'verified', 'new', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, '{"soc":"Broadcom BCM2712, quad-core Cortex-A76 at 2.4 GHz","memory":"4 GB LPDDR4X-4267","gpu":"VideoCore VII","network":"Gigabit Ethernet (PoE+ with HAT), Wi-Fi 802.11ac, Bluetooth 5.0","usb":"2 x USB 3.0, 2 x USB 2.0","display":"Dual 4Kp60 micro HDMI","expansion":"PCIe 2.0 x1, 40-pin GPIO, microSD","power_input":"5V/5A USB-C Power Delivery","supplied":"Board only","sbc_accessory":false,"price_checked":"2026-09-27","source":"PiShop.ca"}'::jsonb),
  ('mini-rpi5-8gb', 'MINI-RPI5-8GB', 'mini-rpi5-8gb', 'mini-pc', 'Raspberry Pi', 'Raspberry Pi 5 / 8GB', 'The 8 GB Pi 5, and the version to pick if it will run several containers at once or double as a small desktop. Roughly three times the CPU throughput of a Pi 4.', 24495, null, 5, 3, null, 'published', 'verified', 'new', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, '{"soc":"Broadcom BCM2712, quad-core Cortex-A76 at 2.4 GHz","memory":"8 GB LPDDR4X-4267","gpu":"VideoCore VII, OpenGL ES 3.1 and Vulkan 1.2","network":"Gigabit Ethernet (PoE+ with HAT), Wi-Fi 802.11ac, Bluetooth 5.0","usb":"2 x USB 3.0 (5 Gbps), 2 x USB 2.0","display":"Dual 4Kp60 micro HDMI with HDR","expansion":"PCIe 2.0 x1, 40-pin GPIO, microSD, real-time clock","power_input":"5V/5A USB-C Power Delivery","supplied":"Board only","sbc_accessory":false,"price_checked":"2026-09-27","source":"PiShop.ca"}'::jsonb),
  ('mini-rpi5-16gb', 'MINI-RPI5-16GB', 'mini-rpi5-16gb', 'mini-pc', 'Raspberry Pi', 'Raspberry Pi 5 / 16GB', 'The 16 GB Pi 5, for a workload that actually needs the memory rather than the cores: a larger container stack, a self-hosted database, or compiling on the board itself.', 42695, null, 5, 3, null, 'published', 'verified', 'new', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, '{"soc":"Broadcom BCM2712, quad-core Cortex-A76 at 2.4 GHz","memory":"16 GB LPDDR4X-4267","gpu":"VideoCore VII, OpenGL ES 3.1 and Vulkan 1.2","network":"Gigabit Ethernet (PoE+ with HAT), Wi-Fi 802.11ac, Bluetooth 5.0","usb":"2 x USB 3.0 (5 Gbps), 2 x USB 2.0","display":"Dual 4Kp60 micro HDMI with HDR","expansion":"PCIe 2.0 x1, 2 x 4-lane MIPI, 40-pin GPIO, microSD, real-time clock","power_input":"5V/5A USB-C Power Delivery","supplied":"Board only","sbc_accessory":false,"price_checked":"2026-09-27","source":"PiShop.ca"}'::jsonb),
  ('mini-rpi5-desktop-kit', 'MINI-RPI5-KIT8', 'mini-rpi5-desktop-kit', 'mini-pc', 'Raspberry Pi', 'Raspberry Pi 5 Desktop Kit (8GB)', 'A complete Pi 5 desktop in one box: board, case, official keyboard and mouse, 27 W supply, both HDMI cables, a preloaded microSD card and the beginner guide. Connect a monitor and it runs.', 28000, null, 5, 3, null, 'published', 'sample', 'new', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, '{"includes":"Raspberry Pi 5 (8 GB), case, keyboard and mouse, 27 W USB-C PD supply, 2 x micro HDMI to HDMI 1 m, 16 GB microSD with Raspberry Pi OS, printed beginner guide","memory":"8 GB LPDDR4X-4267","sbc_accessory":false,"price_checked":"2026-09-27","source":"PiShop.ca","unverified":"The bundled microSD card is listed as carrying the 32-bit OS image. Confirm which image actually ships before advising a customer who wants 64-bit."}'::jsonb),
  ('mini-gigabyte-brix-n150', 'MINI-GB-BRIXN150', 'mini-gigabyte-brix-n150', 'mini-pc', 'GIGABYTE', 'BRIX Intel N150 Barebones', 'A barebones x86 mini PC with Wi-Fi and Bluetooth already fitted. Barebones means no memory, no drive and no operating system, so budget for all three; the payoff is choosing them yourself.', 23900, null, 5, 3, null, 'published', 'sample', 'new', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, '{"cpu":"Intel N150","wireless":"Wi-Fi and Bluetooth included","supplied":"Barebones - no memory, storage or operating system","sbc_accessory":false,"price_checked":"2026-09-27","source":"Canada Computers","unverified":"Memory and storage slot counts, supported capacities and port layout were not stated in the retailer listing. Confirm from the GIGABYTE spec sheet before advising on an upgrade."}'::jsonb),
  ('mini-gigabyte-brix-n250', 'MINI-GB-BRIXN250', 'mini-gigabyte-brix-n250', 'mini-pc', 'GIGABYTE', 'BRIX Intel N250 Barebones', 'The N250 barebones BRIX, a step up from the N150 on the same build-it-yourself terms. A quiet always-on box for a media front end, a small server or a point-of-sale terminal.', 29900, null, 5, 3, null, 'published', 'sample', 'new', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, '{"cpu":"Intel N250","wireless":"Wi-Fi and Bluetooth included","supplied":"Barebones - no memory, storage or operating system","sbc_accessory":false,"price_checked":"2026-09-27","sale_price_observed":"$199.00 on 2026-09-27","source":"Canada Computers","unverified":"Memory and storage slot counts, supported capacities and port layout were not stated in the retailer listing."}'::jsonb),
  ('mini-rpi-active-cooler', 'MINI-RPI-COOLER', 'mini-rpi-active-cooler', 'mini-pc', 'Raspberry Pi', 'Active Cooler for Raspberry Pi 5', 'Clip-on aluminium heatsink with a temperature-controlled blower. A Pi 5 under sustained load will throttle without active cooling, so treat this as part of the board rather than an extra.', 700, null, 5, 3, null, 'published', 'verified', 'new', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, '{"fits":"Raspberry Pi 5","mounting":"Clip-on, uses the board mounting points","control":"Temperature-controlled fan","sbc_accessory":true,"price_checked":"2026-09-27","source":"PiShop.ca"}'::jsonb),
  ('mini-rpi-27w-psu', 'MINI-RPI-PSU27', 'mini-rpi-27w-psu', 'mini-pc', 'Raspberry Pi', '27W USB-C Power Delivery Supply', 'The official 27 W supply. A Pi 5 raises its own USB port budget from roughly 600 mA to 1.6 A only when it detects a PD supply of this class, so a generic charger quietly costs you peripheral power.', 1695, null, 5, 3, null, 'published', 'verified', 'new', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, '{"output":"5.1V/5A, 9V/3A, 12V/2.25A, 15V/1.8A","connector":"USB-C Power Delivery","note":"Unlocks the higher USB port current budget on Raspberry Pi 5","sbc_accessory":true,"price_checked":"2026-09-27","source":"PiShop.ca"}'::jsonb),
  ('mini-rpi-m2-hat', 'MINI-RPI-M2HAT', 'mini-rpi-m2-hat', 'mini-pc', 'Raspberry Pi', 'M.2 HAT+ for Raspberry Pi 5', 'Brings the Pi 5 PCIe lane out to an M.2 slot, so an NVMe drive can replace the microSD card as the boot device. Around 500 MB/s, and a far longer service life than a card under constant writes.', 1695, null, 5, 3, null, 'published', 'verified', 'new', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, '{"interface":"Single-lane PCIe 2.0","supports":"M key M.2 devices, 2230 and 2242 form factors","throughput":"Up to 500 MB/s","power_delivery":"Up to 3 A to the attached device","includes":"16 mm stacking header, threaded spacers, ribbon cable","compatibility":"Fits with the Raspberry Pi Active Cooler in place","sbc_accessory":true,"price_checked":"2026-09-27","source":"PiShop.ca"}'::jsonb)
