-- ---------------------------------------------------------------------------
-- services
-- ---------------------------------------------------------------------------
insert into services (
  id, slug, name, short_description, includes, note, price_text,
  featured, status, sort_order
) values
  ('custom-builds', 'custom-builds', 'Custom PC building', 'A machine assembled from a parts list we have checked together, cabled properly and tested before it leaves.', array['Parts list review against your workload and budget', 'Assembly with cable routing that does not block airflow', 'BIOS configuration and memory profile verification', 'Thermal and stability testing under sustained load', 'Operating system, drivers and updates if requested'], null, null, true, 'published', 10),
  ('upgrades', 'upgrades', 'PC upgrades', 'Adding or replacing parts in a machine you already own, after checking what the existing system can actually take.', array['Compatibility check against your current motherboard, case and power supply', 'Graphics card, memory, storage and cooling upgrades', 'Migration of your existing installation to a new drive where practical', 'Post-upgrade testing so the machine leaves in a known-good state'], 'We will tell you when an upgrade is not worth it. A platform at the end of its upgrade path is better replaced than fed.', null, true, 'published', 20),
  ('diagnostics', 'diagnostics', 'Hardware diagnostics', 'Finding the actual cause of instability, rather than replacing parts until the symptom moves.', array['Memory testing and storage health checks', 'Thermal behaviour under load, including throttling analysis', 'Power delivery and connection inspection', 'Component isolation testing where a fault is not obvious', 'A written summary of what was found and what we recommend'], null, null, true, 'published', 30),
  ('windows', 'windows', 'Windows installation', 'A clean installation, configured and updated, with your data preserved.', array['Clean install of Windows 11 with current updates', 'Partition and drive configuration', 'Data migration from the previous installation where recoverable', 'Recovery media for your specific configuration on request'], 'We need a valid licence for the edition being installed, or you can add one to the order.', null, false, 'published', 40),
  ('drivers', 'drivers', 'Driver and software setup', 'The right drivers from the right source, and the software you actually use, configured.', array['Chipset, graphics, network and storage drivers from vendor sources', 'Firmware and BIOS updates where they address a real issue', 'Application installation and configuration', 'Removal of preinstalled software you did not ask for'], null, null, false, 'published', 50),
  ('optimisation', 'optimisation', 'Performance optimisation', 'Measuring what the machine does now, changing the thing that is actually limiting it, then measuring again.', array['Baseline measurement before any change', 'Memory profile (XMP/EXPO) verification and correction', 'Fan curve tuning for the noise level you want', 'Storage configuration and boot time work', 'Before-and-after figures so the change is visible'], 'Results depend entirely on what was wrong to begin with. We do not promise a percentage in advance.', null, false, 'published', 60),
  ('thermal', 'thermal', 'Thermal testing', 'Sustained load testing to find out what the machine holds, not what it peaks at.', array['Extended load testing with temperature and clock logging', 'Thermal paste and cooler mounting inspection', 'Case airflow assessment and fan configuration', 'Recommendations ordered by what would actually help most'], null, null, false, 'published', 70),
  ('troubleshooting', 'troubleshooting', 'Hardware troubleshooting', 'Machines that will not boot, crash under load, or have started behaving differently.', array['No-boot and no-display diagnosis', 'Crash, freeze and blue screen investigation', 'Peripheral and connectivity faults', 'Post-repair verification before the machine goes back'], null, null, false, 'published', 80)
